ruleSearch.bookList:
@js:
(function() {
  var body = JSON.parse(result).body;
  function tagText(tags) {
    if (!tags) return '';
    return tags.map(function(t) { return (typeof t === 'string') ? t : (t.tag || t.name || ''); }).filter(function(x) { return !!x; }).join(',');
  }
  function mapSingle(v) {
    return {
      name: v.title || '',
      author: v.userName || '',
      bookUrl: 'https://www.pixiv.net/ajax/novel/' + v.id + '?lang=zh',
      coverUrl: v.coverUrl || v.url || '',
      intro: v.description || v.caption || '',
      kind: tagText(v.tags),
      wordCount: v.textCount || v.wordCount || 0,
      lastChapter: v.title || ''
    };
  }
  if (body && body.novel && Array.isArray(body.novel.data)) {
    return body.novel.data.map(function(v) {
      var isSeries = !!v.seriesId;
      return {
        name: v.title || '',
        author: v.userName || '',
        bookUrl: isSeries ? 'https://www.pixiv.net/ajax/novel/series/' + v.seriesId + '?lang=zh' : 'https://www.pixiv.net/ajax/novel/' + v.id + '?lang=zh',
        coverUrl: v.coverUrl || v.url || '',
        intro: v.description || v.caption || '',
        kind: tagText(v.tags),
        wordCount: v.textCount || 0,
        lastChapter: isSeries ? (v.seriesTitle || v.title || '') : (v.title || '')
      };
    });
  }
  if (body && (body.novels || body.novelSeries)) {
    var out = [];
    var seriesIds = {};
    var seriesList = Array.isArray(body.novelSeries) ? body.novelSeries : [];
    seriesList.forEach(function(s) {
      seriesIds[String(s.id)] = true;
      out.push({
        name: s.title || '',
        author: s.userName || '',
        bookUrl: 'https://www.pixiv.net/ajax/novel/series/' + s.id + '?lang=zh',
        coverUrl: s.coverUrl || s.url || '',
        intro: s.caption || s.description || '',
        kind: tagText(s.tags),
        wordCount: s.publishedTotalCharacterCount || s.textCount || 0,
        lastChapter: s.title || ''
      });
    });
    var uidMatch = (typeof baseUrl === 'string' ? baseUrl : '').match(/\/user\/(\d+)\//);
    var uid = uidMatch ? uidMatch[1] : (body.userId || body.id || '');
    var novelIds = [];
    if (body.novels) {
      if (Array.isArray(body.novels)) {
        body.novels.forEach(function(v) { if (v && v.id) novelIds.push(String(v.id)); });
      } else {
        Object.keys(body.novels).forEach(function(id) { novelIds.push(id); });
      }
    }
    if (novelIds.length > 0 && uid) {
      var singles = [];
      var chunk = 30;
      for (var start = 0; start < novelIds.length; start += chunk) {
        var part = novelIds.slice(start, start + chunk);
        try {
          var resp = java.ajax('https://www.pixiv.net/ajax/user/' + uid + '/novels?' + part.map(function(id) { return 'ids[]=' + id; }).join('&') + '&lang=zh');
          if (resp && resp.indexOf('{') >= 0) {
            var b2 = JSON.parse(resp).body;
            var vals = [];
            if (Array.isArray(b2)) vals = b2;
            else if (b2 && b2.novels) vals = Array.isArray(b2.novels) ? b2.novels : Object.keys(b2.novels).map(function(k) { return b2.novels[k]; });
            else if (b2) vals = Object.keys(b2).map(function(k) { return b2[k]; });
            vals.forEach(function(v) { if (v && v.title) singles.push(v); });
          }
        } catch (e) {}
      }
      if (singles.length > 0) {
        singles.reverse().forEach(function(v) {
          var sid = v.seriesId || (v.seriesNavData && v.seriesNavData.seriesId);
          if (sid && seriesIds[String(sid)]) return;
          out.push(mapSingle(v));
        });
      } else if (Array.isArray(body.novels)) {
        body.novels.forEach(function(v) { if (v && v.title) out.push(mapSingle(v)); });
      } else {
        Object.keys(body.novels).forEach(function(id) {
          var v = body.novels[id];
          if (v && v.title) { v.id = v.id || id; out.push(mapSingle(v)); }
        });
      }
    }
    var pm = (typeof baseUrl === 'string' ? baseUrl : '').match(/xunshu_page=(\d+)/);
    if (pm) {
      var pg = parseInt(pm[1], 10) || 1;
      return out.slice((pg - 1) * 30, pg * 30);
    }
    return out;
  }
  return [];
})();

