@js:
(function() {
  var k = key;
  if (k.charAt(0) === '@' || k.charAt(0) === '＠') {
    var name = k.slice(1).trim();
    try {
      var u = java.ajax('https://www.pixiv.net/ajax/search/users?nick=' + encodeURIComponent(name) + '&s_mode=s_usr&i=1&p=1&lang=zh');
      if (u && u.indexOf('{') >= 0) {
        var ub = JSON.parse(u).body;
        var uid = null;
        if (ub) {
          if (Array.isArray(ub.users)) {
            for (var i = 0; i < ub.users.length; i++) {
              var uu = ub.users[i];
              var nm = uu.name || uu.userName || '';
              var id = uu.id || uu.userId || uu.user_id;
              if (nm === name) { uid = id; break; }
              if (!uid) uid = id;
            }
          } else if (ub.page && Array.isArray(ub.page.userIds) && ub.page.userIds.length > 0) {
            uid = ub.page.userIds[0];
          } else if (Array.isArray(ub.userIds) && ub.userIds.length > 0) {
            uid = ub.userIds[0];
          } else if (ub.userId) {
            uid = ub.userId;
          } else if (ub.users && typeof ub.users === 'object') {
            var ks = Object.keys(ub.users);
            if (ks.length > 0) {
              var first = ub.users[ks[0]];
              uid = (first && (first.id || first.userId)) || ks[0];
            }
          }
        }
        if (uid) return 'https://www.pixiv.net/ajax/user/' + uid + '/profile/all?lang=zh&xunshu_page=' + page;
      }
    } catch (e) {}
    return 'https://www.pixiv.net/ajax/search/novels/' + encodeURIComponent(name) + '?word=' + encodeURIComponent(name) + '&order=date_d&mode=all&p=' + page + '&s_mode=s_tag&lang=zh';
  }
  return 'https://www.pixiv.net/ajax/search/novels/' + encodeURIComponent(k) + '?word=' + encodeURIComponent(k) + '&order=date_d&mode=all&p=' + page + '&s_mode=s_tag&lang=zh';
})();
